const circularShift = (x, shift) => {
  const s = String(x);
  const n = s.length;
  if (shift > n) {
    return s.split('').reverse().join('');
  }
  const k = shift % n;
  if (k === 0) return s;
  return s.slice(-k) + s.slice(0, n - k);
};

