const triangleArea = (a, b, c) => {
  // Check for valid triangle
  if (a + b <= c || a + c <= b || b + c <= a) {
    return -1;
  }

  // Heron's formula
  const s = (a + b + c) / 2;
  const area = Math.sqrt(s * (s - a) * (s - b) * (s - c));

  // Round to two decimal places
  return Number(area.toFixed(2));
};

