const isMultiplyPrime = (a) => {
  if (a < 2) return false;
  const isPrime = (n) => {
    if (n < 2) return false;
    if (n === 2) return true;
    if (n % 2 === 0) return false;
    for (let i = 3; i * i <= n; i += 2) {
      if (n % i === 0) return false;
    }
    return true;
  };

  let count = 0;
  let n = a;
  for (let p = 2; p * p <= n; p++) {
    while (n % p === 0) {
      count++;
      n = Math.floor(n / p);
      if (count > 3) return false;
    }
  }
  if (n > 1) count++; // remaining prime factor

  return count === 3;
};

