const isSimplePower = (x, n) => {
  if (x === 1) return true; // 1 is n^0 for any n
  if (n === 1) return x === 1; // only 1^k = 1
  if (n === 0) return false; // 0^k is 0 for k>0, but 0^0 undefined
  if (x < 1 || n < 1) return false; // negative or zero values not considered

  let current = x;
  while (current % n === 0) {
    current = current / n;
  }
  return current === 1;
};

